from pathlib import Path
wt=Path("/Users/steventran/.do_again/lifecycle-ci-20261007")
for rel in [
  "src/do_again/core/schema.py",
  "src/do_again/service/liveness.py",
  "tests/test_liveness.py",
]:
    p=wt/rel
    print(f"===== {rel} =====")
    lines=p.read_text().splitlines()
    if rel.endswith("schema.py"):
        for i,l in enumerate(lines):
            if "continuation" in l.lower() or "goal_state" in l.lower() or "acknowledged_receipts" in l.lower():
                a=max(0,i-8); b=min(len(lines),i+18)
                print(f"--- {a+1}-{b} ---")
                for j in range(a,b): print(f"{j+1}: {lines[j]}")
    elif rel.endswith("liveness.py"):
        for a,b in [(160,280)]:
            for j in range(a-1,min(b,len(lines))): print(f"{j+1}: {lines[j]}")
    else:
        for j in range(1,min(240,len(lines))+1): print(f"{j}: {lines[j-1]}")
